package com.eidolon.sc.mobile;
import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.time.*;import java.io.*;

/** Cache and short, non-blocking context deadline. Viewing Settings never fetches weather. */
final class WeatherRuntime {
 static final ExecutorService FETCH=Executors.newFixedThreadPool(3);
 static final ConcurrentHashMap<String,Future<JSONObject>> FLIGHTS=new ConcurrentHashMap<>();
 static final Object CONFIG_LOCK=new Object();
 static String cacheKey(JSONObject cfg,JSONObject city,boolean tokyo){return "weatherCache/"+cfg.optLong("revision")+"/"+(tokyo?"tokyo":city==null?"none":city.optDouble("latitude")+","+city.optDouble("longitude"));}
 static JSONObject cached(ChatStore s,JSONObject cfg,JSONObject city,boolean tokyo,long now)throws Exception{JSONObject m=SocialStore.meta(s,cacheKey(cfg,city,tokyo)),w=m.optJSONObject("data");return WeatherData.fresh(w,now)?w:null;}
 static Future<JSONObject> request(Context c,JSONObject cfg,JSONObject city,boolean tokyo,boolean force)throws Exception{
  if(!cfg.optBoolean("enabled")||tokyo&&!cfg.optBoolean("tokyo",true)||!tokyo&&(!cfg.optBoolean("user",true)||city==null||cfg.optString("host").isEmpty()))return CompletableFuture.completedFuture(null);String key=cacheKey(cfg,city,tokyo);long now=System.currentTimeMillis();
  synchronized(FLIGHTS){Future<JSONObject> previous=FLIGHTS.get(key);if(previous!=null&&!previous.isDone())return previous;try(ChatStore s=new ChatStore(c)){JSONObject m=SocialStore.meta(s,key),w=m.optJSONObject("data");if(!force&&WeatherData.fresh(w,now))return CompletableFuture.completedFuture(w);if(m.optLong("failedAt")>now||now-m.optLong("failedAt")<10*60000L)return CompletableFuture.completedFuture(null);}
   Future<JSONObject> work=FETCH.submit(()->{try{JSONObject result=tokyo?WeatherClient.tokyo(WeatherClient.guarded(c,cfg,WeatherClient.HTTPS),System.currentTimeMillis()):WeatherClient.user(c,cfg,city,WeatherClient.guarded(c,cfg,city,WeatherClient.HTTPS),System.currentTimeMillis());synchronized(CONFIG_LOCK){try(ChatStore s=new ChatStore(c)){JSONObject actual=SocialStore.weatherConfig(s);if(actual.getLong("revision")!=cfg.getLong("revision")||!actual.getBoolean("enabled")||!tokyo&&!sameCity(city,SocialStore.city(s)))return null;SocialStore.meta(s,key,new JSONObject().put("data",result));}}return result;}catch(Exception e){synchronized(CONFIG_LOCK){try(ChatStore s=new ChatStore(c)){if(SocialStore.weatherConfig(s).getLong("revision")==cfg.getLong("revision")&&(tokyo||sameCity(city,SocialStore.city(s))))SocialStore.meta(s,key,SocialStore.meta(s,key).put("failedAt",System.currentTimeMillis()).put("error","天气获取未完成；缺失项目不提供，稍后可重试"));}}return null;}});FLIGHTS.put(key,work);if(FLIGHTS.size()>40)FLIGHTS.entrySet().removeIf(e->e.getValue().isDone());return work;
  }
 }
 static boolean sameCity(JSONObject a,JSONObject b){return a==null?b==null:b!=null&&Double.compare(a.optDouble("latitude"),b.optDouble("latitude"))==0&&Double.compare(a.optDouble("longitude"),b.optDouble("longitude"))==0;}
 static void retainCityCache(ChatStore s,JSONObject cfg,JSONObject city)throws Exception{String keep=city==null?"":cacheKey(cfg,city,false);List<String> remove=new ArrayList<>();try(android.database.Cursor c=s.getReadableDatabase().rawQuery("SELECT key FROM social_meta WHERE key LIKE 'weatherCache/%'",null)){while(c.moveToNext()){String key=c.getString(0);if(!key.endsWith("/tokyo")&&!key.equals(keep))remove.add(key);}}for(String key:remove)s.getWritableDatabase().delete("social_meta","key=?",new String[]{key});}
 static List<String> obsoleteCredentials(Collection<String> keys,String keep){List<String> remove=new ArrayList<>();for(String key:keys)if(key.matches("(?:configured/)?weather\\.(?:privateKey|apiKey)/[a-f0-9-]{36}")&&!key.endsWith("/"+keep))remove.add(key);return remove;}
 static void pruneCredentials(Context c,String keep){SharedPreferences p=c.getSharedPreferences("vault",0);List<String> remove=obsoleteCredentials(p.getAll().keySet(),keep);boolean ok=true;if(!remove.isEmpty()){SharedPreferences.Editor editor=p.edit();for(String key:remove)editor.remove(key);ok=editor.commit();}SharedPreferences.Editor state=c.getSharedPreferences("settings",0).edit();if(ok)state.remove("weatherCredentialCleanupError");else state.putString("weatherCredentialCleanupError","新配置已保存，但旧加密凭据尚未全部清理，请重新保存或清除");state.apply();}
 static JSONObject waitFor(Future<JSONObject> f,long deadline){try{long left=deadline-System.nanoTime();return left<=0?null:f.get(left,TimeUnit.NANOSECONDS);}catch(Exception e){return null;}}
 static JSONObject[] known(Context c,ChatStore s,boolean force)throws Exception{JSONObject cfg=SocialStore.weatherConfig(s),city=SocialStore.city(s);if(!cfg.getBoolean("enabled"))return new JSONObject[]{null,city,null};Future<JSONObject> a=request(c,cfg,city,true,force),b=request(c,cfg,city,false,force);long deadline=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(force?1500:1200);JSONObject first=waitFor(a,deadline),there=waitFor(b,deadline);synchronized(CONFIG_LOCK){JSONObject actual=SocialStore.weatherConfig(s),selected=SocialStore.city(s);if(!actual.optBoolean("enabled")||actual.optLong("revision")!=cfg.optLong("revision"))return new JSONObject[]{null,selected,null};if(!sameCity(city,selected))there=cached(s,actual,selected,false,System.currentTimeMillis());return new JSONObject[]{first,selected,there};}}
 static String prompt(Context c,ChatStore s,List<ChatStore.Message> history,long now,long apart)throws Exception{JSONObject cfg=SocialStore.weatherConfig(s);if(!cfg.getBoolean("enabled"))return WeatherData.context(null,SocialStore.city(s),null,now,apart,false);JSONObject[] k=known(c,s,false);boolean mentioned=false;for(int i=Math.max(0,history.size()-10);i<history.size();i++){String t=history.get(i).text;if(t.matches("(?s).*(天气|气温|下雨|下雪|天気|雨が|雪が|℃).*")){mentioned=true;break;}}return WeatherData.context(k[0],k[1],k[2],Math.max(now,System.currentTimeMillis()),apart,mentioned);}
 static JSONObject view(Context c,ChatStore s)throws Exception{JSONObject cfg=SocialStore.weatherConfig(s),city=SocialStore.city(s);long now=System.currentTimeMillis();JSONObject out=new JSONObject().put("config",cfg.put("hasPrivateKey",configured(c,cfg,"privateKey")).put("hasApiKey",configured(c,cfg,"apiKey"))).put("city",city==null?JSONObject.NULL:city);out.put("tokyo",cached(s,cfg,city,true,now)).put("there",cached(s,cfg,city,false,now));JSONObject a=SocialStore.meta(s,cacheKey(cfg,city,true)),b=SocialStore.meta(s,cacheKey(cfg,city,false));cfg.remove("credentialSet");out.put("credentialCleanupWarning",c.getSharedPreferences("settings",0).getString("weatherCredentialCleanupError",""));return out.put("tokyoError",a.optString("error")).put("userError",b.optString("error"));}
 static boolean configured(Context c,JSONObject cfg,String name){try{return Vault.configured(c,WeatherClient.credentialSlot(cfg,name));}catch(Exception e){return false;}}
 static JSONObject save(Context c,ChatStore s,JSONObject args)throws Exception{synchronized(CONFIG_LOCK){
  JSONObject old=SocialStore.weatherConfig(s),cfg=new JSONObject().put("enabled",args.optBoolean("enabled")).put("tokyo",args.optBoolean("tokyo",true)).put("user",args.optBoolean("user",true)).put("host",WeatherClient.host(args.optString("host"))).put("auth",args.optString("auth","jwt"));
  if(args.optLong("revision",-1)!=old.getLong("revision"))throw new IOException("天气设置已改变，请重新读取后保存");
  if(!Arrays.asList("jwt","key").contains(cfg.getString("auth")))throw new IOException("认证方式无效");
  for(String k:new String[]{"kid","developer","project"}){String v=args.optString(k).trim();if(v.length()>100||v.contains("\n")||v.contains("\r"))throw new IOException("和风凭据编号无效");cfg.put(k,v);}
  String pem=args.optString("privateKey").trim(),api=args.optString("apiKey").trim();boolean clear=args.optBoolean("clearCredentials"),changed=!old.optString("host").equals(cfg.getString("host"));
  if(pem.length()>8192||api.length()>512||api.contains("\n")||api.contains("\r"))throw new IOException("凭据格式无效");
  if(changed&&!old.optString("host").isEmpty()&&pem.isEmpty()&&api.isEmpty()&&!clear)throw new IOException("更换API Host请重新填写凭据，或先清除旧凭据");
  if(!clear&&!changed&&!old.optString("credentialSet").isEmpty()){
   if(pem.isEmpty())pem=Vault.read(c,WeatherClient.credentialSlot(old,"privateKey"));
   if(api.isEmpty())api=Vault.read(c,WeatherClient.credentialSlot(old,"apiKey"));
  }
  if(clear){pem="";api="";}
  if(!pem.isEmpty()&&cfg.getString("auth").equals("jwt"))QWeatherSigner.sign(pem,cfg.getString("kid"),cfg.getString("developer"),cfg.getString("project"),System.currentTimeMillis());
  // Unique encrypted slots: an interrupted save never puts new credentials behind an old Host.
  cfg.put("credentialSet",UUID.randomUUID().toString()).put("revision",old.getLong("revision")+1);
  Vault.save(c,WeatherClient.credentialSlot(cfg,"privateKey"),pem);Vault.save(c,WeatherClient.credentialSlot(cfg,"apiKey"),api);
  SocialStore.meta(s,"weather",cfg);pruneCredentials(c,cfg.getString("credentialSet"));return view(c,s);
 }}
 static void lookupBudget(ChatStore s,long now)throws Exception{synchronized(CONFIG_LOCK){JSONObject m=SocialStore.meta(s,"cityLookups");long start=m.optLong("start");int count=m.optInt("count");if(now-start>=SocialData.HOUR){start=now;count=0;}if(count>=60||start>now+60000)throw new IOException("城市查找过于频繁，请一小时后再试");SocialStore.meta(s,"cityLookups",new JSONObject().put("start",start==0?now:start).put("count",count+1));}}
 static JSONArray search(Context c,ChatStore s,String query)throws Exception{String q=query.trim();if(q.isEmpty()||q.length()>80)throw new IOException("请输入1至80字的城市名");long now=System.currentTimeMillis();JSONObject cfg=SocialStore.weatherConfig(s);lookupBudget(s,now);return WeatherClient.search(c,cfg,q,WeatherClient.HTTPS,now);}
 static JSONObject nearest(Context c,double lat,double lon)throws Exception{try(ChatStore s=new ChatStore(c)){JSONArray a=search(c,s,WeatherClient.location(lat,lon));return a.length()==0?null:a.getJSONObject(0);}}
}
